from taf.fdsw.rc.interfaces.FDSW23D.fdsw import FDSW23D
from taf.fdsw.rc.interfaces.FDSW24A.autoconnection import AutoConfiguration24A


class FDSW24A(FDSW23D):
    VERSION_NAME = 'FDSW24A'
    _client = None

    def __init__(self, ip_address, port, username, password, secure=True):
        super(FDSW24A, self).__init__(ip_address=ip_address, port=port, username=username, password=password, secure=secure)
        self.autoconnection = AutoConfiguration24A(client=self._client)
